// Collect every non-sponsored shop Google Maps returns around a place or coordinate.
// The result list is paginated with its public "See more" control. Store details are
// read from the visible result cards, so the browser does not reload each place page.

// Phase 1: validate the requested search scope.
const locationInput = String(tobub.params.location ?? '').trim();
const requestedLimit = Number(tobub.params.limit ?? 20);
const SAFETY_MAX_RESULTS = 1000;
const INITIAL_SEARCH_RADIUS_KM = 2;
const MAX_SEARCH_RADIUS_KM = Number(tobub.params.max_radius_km ?? 5);
const SEARCH_ZOOM = Number(tobub.params.search_zoom ?? 15);
if (!Number.isInteger(SEARCH_ZOOM) || SEARCH_ZOOM < 14 || SEARCH_ZOOM > 21) {
  throw new Error('search_zoom must be an integer from 14 to 21.');
}
if (!Number.isFinite(MAX_SEARCH_RADIUS_KM) || MAX_SEARCH_RADIUS_KM < 0.5 || MAX_SEARCH_RADIUS_KM > 10) {
  throw new Error('max_radius_km must be between 0.5 and 10.');
}
const INITIAL_RADIUS_KM = Math.min(INITIAL_SEARCH_RADIUS_KM, MAX_SEARCH_RADIUS_KM);
const COVERAGE_ZOOM = 15;
const MAX_COVERAGE_TILES = 120;
const MAX_TILE_RESULT_BATCHES = 20;
// Zoom 20 is included as a second ranked-result pass because Maps returned a different
// place set there during live validation. Keep it fixed and visible in the output.
const SEARCH_ZOOMS = Array.from(new Set([SEARCH_ZOOM, 20]));
const MAX_RESULT_BATCHES = 150;
const MAX_QUERY_LOAD_ATTEMPTS = 2;
const MAP_NAVIGATION_TIMEOUT_MS = 30000;
// Navigate Maps until the response commits, then wait for the result feed separately.
// Maps is a client-rendered app; waiting for DOMContentLoaded on every tile timed out live.
const navigateMapsUrl = async (url) => {
  const expression = `async (page) => {
    await page.goto(${JSON.stringify(url)}, {
      waitUntil: 'commit',
      timeout: ${MAP_NAVIGATION_TIMEOUT_MS},
    });
  }`;
  await tobub.atoms.evaluate({ scope: 'playwright', expression }, {
    timeout: MAP_NAVIGATION_TIMEOUT_MS + 5000,
  });
};
const MAX_QUERY_PASSES = 2;

if (!locationInput) throw new Error('location is required. Enter an address or latitude,longitude.');
if (!Number.isInteger(requestedLimit) || requestedLimit < 0 || requestedLimit > SAFETY_MAX_RESULTS) {
  throw new Error(`limit must be 0 (all available results) or an integer from 1 to ${SAFETY_MAX_RESULTS}.`);
}

const effectiveLimit = requestedLimit || SAFETY_MAX_RESULTS;

function parseCoordinates(value) {
  const match = String(value).match(/^\s*(-?\d{1,2}(?:\.\d+)?)\s*,\s*(-?\d{1,3}(?:\.\d+)?)\s*$/);
  if (!match) return null;
  const lat = Number(match[1]);
  const lng = Number(match[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
    throw new Error('Coordinates are out of range. Latitude must be -90 to 90 and longitude -180 to 180.');
  }
  return { lat, lng };
}

function coordinatesFromUrl(value) {
  const url = String(value ?? '');
  const at = url.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);
  if (at) return { lat: Number(at[1]), lng: Number(at[2]) };
  const place = url.match(/!3d(-?\d+(?:\.\d+)?)!4d(-?\d+(?:\.\d+)?)/);
  if (place) return { lat: Number(place[1]), lng: Number(place[2]) };
  return null;
}

function cleanText(value) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return text || null;
}

const isBrowserUnavailableError = (message) =>
  /(?:main page|browser page|page|browser|context|target).*(?:closed|no longer available)|(?:closed|no longer available).*(?:main page|browser page|page|browser|context|target)/i
    .test(String(message ?? ''));

function cleanPhone(value) {
  const text = cleanText(value);
  return text && /^(?:n\/?a|not available|none|-)$/i.test(text) ? null : text;
}

function parseRating(value) {
  const match = String(value ?? '').trim().match(/(?:^|\b)([0-5](?:[.,]\d)?)(?:\s*(?:stars?|星级|星)|\s*\()/i);
  return match ? Number(match[1].replace(',', '.')) : null;
}

function parseReviewCount(value) {
  const text = String(value ?? '').trim();
  const ratingCount = text.match(/^[0-5](?:[.,]\d)?\s*\(\s*([\d,.]+)\s*\)$/);
  const labeledCount = text.match(/([\d,\.]+)\s*(?:reviews?|评价|条评价)/i);
  const match = ratingCount || labeledCount;
  if (!match) return null;
  const count = Number(match[1].replace(/[,.]/g, ''));
  return Number.isFinite(count) ? count : null;
}

function distanceKm(a, b) {
  const radians = (degrees) => degrees * Math.PI / 180;
  const deltaLat = radians(b.lat - a.lat);
  const deltaLng = radians(b.lng - a.lng);
  const halfChord = Math.sin(deltaLat / 2) ** 2
    + Math.cos(radians(a.lat)) * Math.cos(radians(b.lat)) * Math.sin(deltaLng / 2) ** 2;
  return 6371 * 2 * Math.asin(Math.sqrt(halfChord));
}

async function readPage(expression) {
  return (await tobub.atoms.evaluate({ expression: expression.toString() })).value;
}

// Phase 2: resolve the input to a stable coordinate center.
let center = parseCoordinates(locationInput);
if (!center) {
  const addressUrl = 'https://www.google.com/maps/search/' + encodeURIComponent(locationInput) + '?hl=en';
  await navigateMapsUrl(addressUrl);

  const addressExpression = () => {
    const firstPlace = Array.from(document.querySelectorAll('[role="feed"] [role="article"] a[href*="/maps/place/"]'))
      .filter((link) => !/\b(Sponsored|赞助商|广告)\b/i.test(link.closest('[role="article"]')?.innerText || ''))
      .map((link) => ({ href: link.href, label: link.getAttribute('aria-label') || link.innerText || '' }))[0] || null;
    return { url: location.href, firstPlace };
  };

  const addressReadyExpression = async (page) => {
    await page.waitForFunction(() => {
      const firstPlace = Array.from(document.querySelectorAll('[role="feed"] [role="article"] a[href*="/maps/place/"]'))
        .find((link) => !/\b(Sponsored|赞助商|广告)\b/i.test(link.closest('[role="article"]')?.innerText || ''));
      return Boolean(firstPlace) || /@-?\d+(?:\.\d+)?,-?\d+(?:\.\d+)?/.test(location.href);
    }, null, { timeout: 12000, polling: 250 });
  };
  try {
    await tobub.atoms.evaluate({ scope: 'playwright', expression: addressReadyExpression.toString() }, { timeout: 15000 });
  } catch {
    // The explicit resolution check below returns the useful error message.
  }
  const addressState = await readPage(addressExpression);
  center = coordinatesFromUrl(addressState.firstPlace?.href) || coordinatesFromUrl(addressState.url);

  if (!center) {
    throw new Error('Could not resolve this address to a Google Maps place. Try a more specific address or latitude,longitude.');
  }
}

// Phase 3: read and paginate each configured Google Maps result feed.
// The collector merges different ranked lists by stable Place ID and filters each
// candidate against the original center and radius.
const listingExpression = () => {
  const feed = document.querySelector('[role="feed"]');
  if (!feed) {
    return {
      candidates: [], cardCount: 0, hasFeed: false, hasMore: false,
      scrollTop: 0, scrollHeight: 0, clientHeight: 0,
      pageText: (document.body?.innerText || '').slice(0, 500),
    };
  }

  const cards = Array.from(feed.querySelectorAll('[role="article"]'));
  const candidates = [];
  for (const card of cards) {
    const link = card.querySelector('a[href*="/maps/place/"]');
    if (!link) continue;

    const text = (card.innerText || '').trim();
    const sponsoredHeading = Array.from(card.querySelectorAll('h1,h2,h3'))
      .some((heading) => /^(Sponsored|Ad|赞助商|广告)$/i.test((heading.innerText || '').trim()));
    if (sponsoredHeading || /(^|\n)\s*(Sponsored|赞助商|广告)\s*(\n|$)/i.test(text)) continue;

    const href = link.href.split('?')[0] + '?hl=en';
    const placeId = href.match(/!1s([^!?#]+)/)?.[1] || href;
    const cardLines = text.split('\n').map((line) => line.trim()).filter(Boolean);
    const name = (link.getAttribute('aria-label') || link.innerText || '').trim();
    const ratingLine = cardLines.find((line) => /^[0-5](?:[.,]\d)?\s*\(\s*[\d,.]+\s*\)$/.test(line)) || '';
    const accessibleRating = Array.from(card.querySelectorAll('[role="img"][aria-label], span[aria-label]'))
      .map((element) => element.getAttribute('aria-label') || '')
      .find((label) => /[0-5](?:[.,]\d)?\s*(?:stars?|星级|星)/i.test(label)) || '';
    const ratingLabel = accessibleRating || ratingLine;

    const detailLines = cardLines.filter((line) => line !== name && line !== ratingLine);
    const rawMetadataLine = detailLines.find((line) => /[·•]/.test(line)
      && !/\b(open|closed|opens|temporarily|permanently)\b/i.test(line)) || '';
    const metadataLine = rawMetadataLine.split(/\b(?:open|closed|opens|temporarily|permanently)\b/i)[0].trim();
    const metadataParts = metadataLine.split(/[·•]/)
      .map((part) => part.replace(/\s+/g, ' ').trim())
      .filter((part) => part && !/^[\uE000-\uF8FF\s]+$/.test(part));
    const category = metadataParts[0] || null;
    const metadataTail = metadataParts.slice(1).join(' · ');
    const addressPattern = /(?:Pier\s+\d+\s*,?\s*)?\d{1,5}\s+[^·•\n,]{1,50}?\b(?:street|st|avenue|ave|road|rd|boulevard|blvd|way|wy|drive|dr|lane|ln|alley|aly|pike|place|pl|highway|hwy|terrace|ter|court|ct)\b(?:\s*(?:#|suite|ste|apt|unit)\s*[\w-]+)?/i;
    const addressMatch = metadataTail.match(addressPattern);
    const address = addressMatch?.[0] || metadataParts[1] || null;

    const textSegments = text.split(/[·•\n]/).map((segment) => segment.trim()).filter(Boolean);
    const phone = textSegments.slice().reverse().find((segment) => {
      const digits = segment.replace(/\D/g, '');
      return digits.length >= 7 && digits.length <= 15 && /^[+\d\s().-]+$/.test(segment);
    }) || null;
    const hours = textSegments
      .filter((segment) => /\b(open|closed|opens|temporarily|permanently)\b/i.test(segment))
      .join(' · ') || null;
    const description = addressMatch
      ? (metadataTail.replace(addressMatch[0], '').replace(/^[·•\s]+/, '').replace(/\s+/g, ' ').trim() || null)
      : null;

    candidates.push({
      id: placeId,
      name: name.trim(),
      category,
      rating_label: ratingLabel,
      reviews_label: ratingLine || text,
      address,
      phone,
      hours,
      description,
      href,
      card_text: text,
    });
  }

  const moreButton = Array.from(feed.querySelectorAll('button')).find((button) => {
    const label = (button.getAttribute('aria-label') || button.innerText || '').trim();
    const style = window.getComputedStyle(button);
    const visible = button.getClientRects().length > 0
      && style.display !== 'none'
      && style.visibility !== 'hidden'
      && Number(style.opacity) !== 0;
    return visible
      && !button.closest('[role="article"]')
      && /^(See more|More results|查看更多|查看更多结果)$/i.test(label);
  });
  return {
    candidates,
    cardCount: cards.length,
    hasFeed: true,
    hasMore: Boolean(moreButton),
    scrollTop: feed.scrollTop,
    scrollHeight: feed.scrollHeight,
    clientHeight: feed.clientHeight,
    pageText: (document.body?.innerText || '').slice(0, 500),
  };
};

// Scroll the visible result feed only. Never click result or generic "See more" controls;
// Google Maps uses similarly named controls for place navigation and external viewers.
const loadNextBatchExpression = (previousCardCount, previousPlaceHrefs) => `async (page) => {
  const feed = page.locator('[role="feed"]').first();
  if (!(await feed.count())) return false;
  const beforePath = await page.evaluate(() => location.pathname);
  if (!beforePath.startsWith('/maps/search/')) return false;

  await feed.evaluate((element) => element.scrollBy({
    top: Math.max(element.clientHeight, 700),
    behavior: 'instant',
  }));
  const progressed = await page.waitForFunction((previous) => {
    const currentFeed = document.querySelector('[role="feed"]');
    if (!currentFeed || !location.pathname.startsWith('/maps/search/')) return false;
    const cards = Array.from(currentFeed.querySelectorAll('[role="article"]'));
    if (cards.length > previous.cardCount) return true;
    const hrefs = cards.flatMap((card) => Array.from(card.querySelectorAll('a[href*="/maps/place/"]'))
      .map((link) => link.href.split('?')[0] + '?hl=en'));
    return hrefs.some((href) => !previous.hrefs.includes(href));
  }, { cardCount: ${previousCardCount}, hrefs: ${JSON.stringify(previousPlaceHrefs)} },
  { timeout: 8000, polling: 250 }).then(() => true).catch(() => false);
  const afterPath = await page.evaluate(() => location.pathname);
  return afterPath.startsWith('/maps/search/') && progressed;
}`

// Phase 4: cache stable Place IDs, then rebuild the eligible nearest-first result set
// whenever the active radius expands. This lets later overlapping map tiles promote
// previously observed outer candidates without duplicating or losing them.
const recordsById = new Map();
const seenPlaceIds = new Set();
const foundZoomsById = new Map();
const candidateById = new Map();
let activeRadiusKm = INITIAL_RADIUS_KM;
let outOfRadiusCount = 0;
let missingCoordinatesCount = 0;
let excludedAccommodationCount = 0;
const accommodationPattern = /\b(?:apartment|lodging|hotel|motel|hostel|resort|vacation rental|bed and breakfast|guest house|inn)\b|\b(?:sleeps?\s+\d+|\d+\s+bedrooms?)\b|\bblueground\b/i;

const refreshRecords = () => {
  recordsById.clear();
  outOfRadiusCount = 0;
  missingCoordinatesCount = 0;
  excludedAccommodationCount = 0;
  const eligible = [];
  for (const candidate of candidateById.values()) {
    if (!candidate.name) continue;
    const coordinates = coordinatesFromUrl(candidate.href);
    if (!coordinates) {
      missingCoordinatesCount += 1;
      continue;
    }
    const distance = distanceKm(center, coordinates);
    if (distance > activeRadiusKm) {
      outOfRadiusCount += 1;
      continue;
    }
    if (accommodationPattern.test(`${candidate.category || ''} ${candidate.name} ${candidate.card_text || ''}`)) {
      excludedAccommodationCount += 1;
      continue;
    }
    const foundAtZooms = foundZoomsById.get(candidate.id) || [];
    eligible.push({
      id: candidate.id,
      name: cleanText(candidate.name),
      category: cleanText(candidate.category),
      rating: parseRating(candidate.rating_label),
      reviews_count: parseReviewCount(candidate.reviews_label),
      address: cleanText(candidate.address),
      phone: cleanPhone(candidate.phone),
      website: null,
      hours: cleanText(candidate.hours),
      description: cleanText(candidate.description),
      latitude: coordinates.lat,
      longitude: coordinates.lng,
      distance_km: Number(distance.toFixed(3)),
      url: candidate.href,
      source_card_text: cleanText(candidate.card_text),
      found_at_zooms: [...foundAtZooms],
    });
  }
  eligible.sort((a, b) => a.distance_km - b.distance_km || String(a.name).localeCompare(String(b.name)));
  for (const record of eligible.slice(0, effectiveLimit)) recordsById.set(record.id, record);
};

const addCandidates = (listing, zoom) => {
  let newPlaceCount = 0;
  for (const candidate of listing?.candidates || []) {
    if (!candidate.id) continue;
    let foundAtZooms = foundZoomsById.get(candidate.id);
    if (!foundAtZooms) {
      foundAtZooms = [];
      foundZoomsById.set(candidate.id, foundAtZooms);
    }
    if (!foundAtZooms.includes(zoom)) foundAtZooms.push(zoom);
    seenPlaceIds.add(candidate.id);
    if (!candidateById.has(candidate.id)) {
      candidateById.set(candidate.id, candidate);
      newPlaceCount += 1;
    } else {
      const stored = candidateById.get(candidate.id);
      for (const key of ['name', 'category', 'rating_label', 'reviews_label', 'address', 'phone', 'hours', 'description', 'href', 'card_text']) {
        if (!stored[key] && candidate[key]) stored[key] = candidate[key];
      }
    }
  }
  refreshRecords();
  return newPlaceCount;
};

const resultsReadyExpression = async (page) => {
  await page.waitForFunction(() => {
    const feed = document.querySelector('[role="feed"]');
    return Boolean(feed?.querySelector('[role="article"]'));
  }, null, { timeout: 12000, polling: 250 });
};
const searchPageStateExpression = () => ({
  url: location.href,
  isSearchPage: location.pathname.startsWith('/maps/search/'),
});
const restoreSearchPageAfterPaginationNavigation = async (searchUrl) => {
  const pageState = await readPage(searchPageStateExpression);
  if (pageState.isSearchPage) return null;
  await navigateMapsUrl(searchUrl);
  try {
    await tobub.atoms.evaluate({ scope: 'playwright', expression: resultsReadyExpression.toString() }, { timeout: 15000 });
  } catch {}
  return pageState.url;
};
const searchUrls = SEARCH_ZOOMS.map((zoom) =>
  `https://www.google.com/maps/search/shops/@${center.lat},${center.lng},${zoom}z?hl=en`
);
const searches = [];
let batchesLoaded = 0;
let stopReason = '';
let browserUnavailable = false;

for (let searchIndex = 0; searchIndex < SEARCH_ZOOMS.length; searchIndex += 1) {
  const zoom = SEARCH_ZOOMS[searchIndex];
  const searchUrl = searchUrls[searchIndex];

  for (let pass = 1; pass <= MAX_QUERY_PASSES; pass += 1) {
    if (recordsById.size >= effectiveLimit) {
      stopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
      break;
    }

    const candidatesBeforeSearch = seenPlaceIds.size;
    const recordsBeforeSearch = recordsById.size;
    let listing = null;
    let loadError = null;
    let validEmptyResult = false;

    for (let attempt = 1; attempt <= MAX_QUERY_LOAD_ATTEMPTS; attempt += 1) {
      try {
        await navigateMapsUrl(searchUrl);
        try {
          await tobub.atoms.evaluate({ scope: 'playwright', expression: resultsReadyExpression.toString() }, { timeout: 15000 });
        } catch {
          // Inspect the current page below; the feed may be empty or slow to render.
        }
        listing = await readPage(listingExpression);
        if (listing?.hasFeed && listing.cardCount > 0) {
          loadError = null;
          break;
        }

        const pageText = cleanText(listing?.pageText) || '';
        if (/unusual traffic|not a robot|captcha|unfortunately/i.test(pageText)) {
          loadError = 'Google Maps is showing an access challenge.';
        } else if (/no results|没有结果|找不到结果/i.test(pageText)) {
          validEmptyResult = true;
          loadError = null;
          break;
        } else {
          loadError = 'Google Maps did not render a result feed.';
        }
      } catch (error) {
        loadError = String(error?.message || error || 'Unknown page-load error');
        listing = null;
        if (isBrowserUnavailableError(loadError)) {
          browserUnavailable = true;
          break;
        }
      }
    }

    if (!listing?.hasFeed || !listing.cardCount) {
      const empty = validEmptyResult && !loadError;
      const emptySummary = {
        pass,
        search_zoom: zoom,
        search_url: searchUrl,
        status: empty ? 'empty' : 'failed',
        stop_reason: empty ? 'all_results_loaded' : 'query_failed',
        unique_candidates_seen: seenPlaceIds.size - candidatesBeforeSearch,
        records_added: recordsById.size - recordsBeforeSearch,
        batches_loaded: 0,
        has_more_results: !empty,
        error: loadError,
      };
      searches.push(emptySummary);
      if (browserUnavailable) {
        stopReason = 'query_failed';
        break;
      }
      if (!empty && pass < MAX_QUERY_PASSES) continue;
      break;
    }

    batchesLoaded += 1;
    let queryBatchesLoaded = 1;
    let idleBatches = 0;
    let queryStopReason = '';
    addCandidates(listing, zoom);
    if (recordsById.size >= effectiveLimit) {
      queryStopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
    }

    for (let batch = 0; !queryStopReason && batch < MAX_RESULT_BATCHES && recordsById.size < effectiveLimit; batch += 1) {
      const previousSeenCount = seenPlaceIds.size;
      const canScroll = listing.scrollTop + listing.clientHeight < listing.scrollHeight - 12;
      if (!listing.hasMore && !canScroll) {
        queryStopReason = 'all_results_loaded';
        break;
      }

      try {
        await tobub.atoms.evaluate({
          scope: 'playwright',
          expression: loadNextBatchExpression(listing.cardCount, listing.candidates.map((candidate) => candidate.href)),
        }, { timeout: 12000 });
      } catch {
        // Re-read the feed after the interaction, including when Maps has no next batch.
      }
      let navigatedToDetailUrl = null;
      try {
        navigatedToDetailUrl = await restoreSearchPageAfterPaginationNavigation(searchUrl);
      } catch (error) {
        queryStopReason = 'query_failed';
        loadError = String(error?.message || error || 'Could not verify the results page after pagination.');
        if (isBrowserUnavailableError(loadError)) browserUnavailable = true;
        break;
      }
      if (navigatedToDetailUrl) {
        queryStopReason = 'query_failed';
        loadError = 'Pagination left the Google Maps results page. The search was restored and this query was stopped safely.';
        break;
      }
      try {
        listing = await readPage(listingExpression);
      } catch (error) {
        queryStopReason = 'query_failed';
        loadError = String(error?.message || error || 'Could not read the result feed.');
        break;
      }
      addCandidates(listing, zoom);
      const grew = seenPlaceIds.size > previousSeenCount;
      if (grew) {
        batchesLoaded += 1;
        queryBatchesLoaded += 1;
      }

      if (recordsById.size >= effectiveLimit) {
        queryStopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
        break;
      }
      if (grew) {
        idleBatches = 0;
        continue;
      }
      if (!listing.hasMore && listing.scrollTop + listing.clientHeight >= listing.scrollHeight - 12) {
        queryStopReason = 'all_results_loaded';
        break;
      }

      idleBatches += 1;
      if (idleBatches >= 2) {
        queryStopReason = 'no_new_results';
        break;
      }
    }

    if (!queryStopReason) queryStopReason = recordsById.size >= SAFETY_MAX_RESULTS ? 'safety_cap' : 'batch_cap';
    const queryHasMore = Boolean(listing?.hasMore)
      || ['safety_cap', 'batch_cap', 'no_new_results', 'query_failed'].includes(queryStopReason);
    searches.push({
      pass,
      search_zoom: zoom,
      search_url: searchUrl,
      status: queryStopReason === 'all_results_loaded' ? 'complete'
        : queryStopReason === 'limit_reached' ? 'target_met'
          : 'partial',
      stop_reason: queryStopReason,
      unique_candidates_seen: seenPlaceIds.size - candidatesBeforeSearch,
      records_added: recordsById.size - recordsBeforeSearch,
      batches_loaded: queryBatchesLoaded,
      has_more_results: queryHasMore,
      error: loadError,
    });

    if (queryStopReason === 'limit_reached') {
      stopReason = 'limit_reached';
      break;
    }
    if (queryStopReason === 'safety_cap') {
      stopReason = 'safety_cap';
      break;
    }
    if (queryStopReason === 'batch_cap') {
      stopReason = 'batch_cap';
      break;
    }
    if (queryStopReason === 'all_results_loaded') break;
    // A healthy feed with no new Place IDs is exhausted for this pass; reloading
    // the same search URL adds latency without recovering records. Retry only failures.
    if (browserUnavailable) {
      stopReason = 'query_failed';
      break;
    }
    if (pass < MAX_QUERY_PASSES && queryStopReason === 'query_failed') continue;
    break;
  }

  if (browserUnavailable) {
    stopReason = 'query_failed';
    break;
  }
  if (['limit_reached', 'safety_cap', 'batch_cap'].includes(stopReason)) break;
}

// Phase 4b: expand coverage across overlapping map-sized coordinate tiles, nearest first.
// Tile spacing is estimated from the live browser/map viewport at COVERAGE_ZOOM; each
// tile is a fresh Maps search center, not a pan gesture with ambiguous final coordinates.
const viewportInfoExpression = () => {
  const canvasWidths = Array.from(document.querySelectorAll('canvas'))
    .map((canvas) => {
      const rect = canvas.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0 ? rect.width : 0;
    })
    .sort((a, b) => b - a);
  return {
    viewportWidth: Number(window.innerWidth) || 0,
    mapCanvasWidth: canvasWidths[0] || 0,
  };
};
let viewportInfo = { viewportWidth: 0, mapCanvasWidth: 0 };
try { viewportInfo = await readPage(viewportInfoExpression); } catch {}
const coverageMapWidthPx = viewportInfo.mapCanvasWidth || viewportInfo.viewportWidth * 0.62;
const metersPerPixel = 156543.03392 * Math.cos(center.lat * Math.PI / 180) / (2 ** COVERAGE_ZOOM);
const coverageTileStepKm = Math.max(0.45, Math.min(1.5, metersPerPixel * coverageMapWidthPx * 0.5 / 1000));
const tileOverlapMarginKm = coverageTileStepKm * 0.55;

function coordinateOffset(origin, eastKm, northKm) {
  const latitude = origin.lat + northKm / 111.32;
  const longitude = origin.lng + eastKm / (111.32 * Math.max(0.01, Math.cos(origin.lat * Math.PI / 180)));
  return { lat: Number(latitude.toFixed(6)), lng: Number(longitude.toFixed(6)) };
}

function buildCoverageTiles(maxRadiusKm, stepKm) {
  const halfCount = Math.ceil((maxRadiusKm + stepKm) / stepKm);
  const tiles = [];
  for (let row = -halfCount; row <= halfCount; row += 1) {
    for (let column = -halfCount; column <= halfCount; column += 1) {
      const eastKm = column * stepKm;
      const northKm = row * stepKm;
      const radialDistanceKm = Math.hypot(eastKm, northKm);
      if (radialDistanceKm < stepKm * 0.45 || radialDistanceKm > maxRadiusKm + tileOverlapMarginKm) continue;
      tiles.push({
        east_km: Number(eastKm.toFixed(3)),
        north_km: Number(northKm.toFixed(3)),
        distance_km: Number(radialDistanceKm.toFixed(3)),
        center: coordinateOffset(center, eastKm, northKm),
        key: `${row}:${column}`,
      });
    }
  }
  tiles.sort((a, b) => a.distance_km - b.distance_km || a.north_km - b.north_km || a.east_km - b.east_km);
  return tiles;
}

const coverageTiles = buildCoverageTiles(MAX_SEARCH_RADIUS_KM, coverageTileStepKm);
const searchedTileKeys = new Set();
let tileSearchCount = 0;
let tileFailureCount = 0;
let consecutiveTileFailures = 0;
let tileCapReached = false;
let radiusStage = INITIAL_RADIUS_KM;
const radiusStages = [];
while (radiusStage < MAX_SEARCH_RADIUS_KM) {
  radiusStages.push(Number(radiusStage.toFixed(3)));
  radiusStage = Math.min(MAX_SEARCH_RADIUS_KM, radiusStage + 1);
}
radiusStages.push(Number(MAX_SEARCH_RADIUS_KM.toFixed(3)));

coverageSweep: for (const stageRadiusKm of [...new Set(radiusStages)]) {
  if (browserUnavailable) {
    stopReason = 'query_failed';
    break;
  }
  activeRadiusKm = stageRadiusKm;
  refreshRecords();
  if (recordsById.size >= effectiveLimit) {
    stopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
    break;
  }
  const stageTiles = coverageTiles.filter((tile) =>
    tile.distance_km <= stageRadiusKm + tileOverlapMarginKm && !searchedTileKeys.has(tile.key)
  );
  for (const tile of stageTiles) {
    if (recordsById.size >= effectiveLimit) {
      stopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
      break coverageSweep;
    }
    if (tileSearchCount >= MAX_COVERAGE_TILES) {
      tileCapReached = true;
      stopReason = 'tile_cap';
      break coverageSweep;
    }
    searchedTileKeys.add(tile.key);
    tileSearchCount += 1;
    const tileIndex = tileSearchCount;
    const searchUrl = `https://www.google.com/maps/search/shops/@${tile.center.lat},${tile.center.lng},${COVERAGE_ZOOM}z?hl=en`;
    const candidatesBeforeSearch = seenPlaceIds.size;
    const recordsBeforeSearch = recordsById.size;
    let listing = null;
    let loadError = null;
    let validEmptyResult = false;

    for (let attempt = 1; attempt <= MAX_QUERY_LOAD_ATTEMPTS; attempt += 1) {
      try {
        await navigateMapsUrl(searchUrl);
        try {
          await tobub.atoms.evaluate({ scope: 'playwright', expression: resultsReadyExpression.toString() }, { timeout: 15000 });
        } catch {}
        listing = await readPage(listingExpression);
        if (listing?.hasFeed && listing.cardCount > 0) {
          loadError = null;
          break;
        }
        const pageText = cleanText(listing?.pageText) || '';
        if (/unusual traffic|not a robot|captcha|unfortunately/i.test(pageText)) {
          loadError = 'Google Maps is showing an access challenge.';
        } else if (/no results|没有结果|找不到结果/i.test(pageText)) {
          validEmptyResult = true;
          loadError = null;
          break;
        } else {
          loadError = 'Google Maps did not render a result feed.';
        }
      } catch (error) {
        loadError = String(error?.message || error || 'Unknown tile-load error');
        listing = null;
        if (isBrowserUnavailableError(loadError)) {
          browserUnavailable = true;
          break;
        }
      }
    }

    if (!listing?.hasFeed || !listing.cardCount) {
      const empty = validEmptyResult && !loadError;
      if (!empty) {
        tileFailureCount += 1;
        consecutiveTileFailures += 1;
      } else {
        consecutiveTileFailures = 0;
      }
      searches.push({
        pass: 1,
        search_zoom: COVERAGE_ZOOM,
        search_url: searchUrl,
        search_center: tile.center,
        search_radius_stage_km: stageRadiusKm,
        tile_index: tileIndex,
        tile_distance_km: tile.distance_km,
        status: empty ? 'empty' : 'failed',
        stop_reason: empty ? 'all_results_loaded' : 'query_failed',
        unique_candidates_seen: seenPlaceIds.size - candidatesBeforeSearch,
        records_added: recordsById.size - recordsBeforeSearch,
        batches_loaded: 0,
        has_more_results: !empty,
        error: loadError,
      });
      if (!empty && (browserUnavailable || consecutiveTileFailures >= 2)) {
        stopReason = 'query_failed';
        break coverageSweep;
      }
      continue;
    }

    consecutiveTileFailures = 0;
    batchesLoaded += 1;
    let queryBatchesLoaded = 1;
    let idleBatches = 0;
    let queryStopReason = '';
    addCandidates(listing, COVERAGE_ZOOM);
    if (recordsById.size >= effectiveLimit) queryStopReason = requestedLimit ? 'limit_reached' : 'safety_cap';

    for (let batch = 0; !queryStopReason && batch < MAX_TILE_RESULT_BATCHES && recordsById.size < effectiveLimit; batch += 1) {
      const previousSeenCount = seenPlaceIds.size;
      const canScroll = listing.scrollTop + listing.clientHeight < listing.scrollHeight - 12;
      if (!listing.hasMore && !canScroll) {
        queryStopReason = 'all_results_loaded';
        break;
      }
      try {
        await tobub.atoms.evaluate({
          scope: 'playwright',
          expression: loadNextBatchExpression(listing.cardCount, listing.candidates.map((candidate) => candidate.href)),
        }, { timeout: 12000 });
      } catch {}
      let navigatedToDetailUrl = null;
      try {
        navigatedToDetailUrl = await restoreSearchPageAfterPaginationNavigation(searchUrl);
      } catch (error) {
        queryStopReason = 'query_failed';
        loadError = String(error?.message || error || 'Could not verify the results page after pagination.');
        if (isBrowserUnavailableError(loadError)) browserUnavailable = true;
        break;
      }
      if (navigatedToDetailUrl) {
        queryStopReason = 'query_failed';
        loadError = 'Pagination left the Google Maps results page. The search was restored and this tile was stopped safely.';
        break;
      }
      try {
        listing = await readPage(listingExpression);
      } catch (error) {
        queryStopReason = 'query_failed';
        loadError = String(error?.message || error || 'Could not read the tile result feed.');
        break;
      }
      addCandidates(listing, COVERAGE_ZOOM);
      const grew = seenPlaceIds.size > previousSeenCount;
      if (grew) {
        batchesLoaded += 1;
        queryBatchesLoaded += 1;
      }
      if (recordsById.size >= effectiveLimit) {
        queryStopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
        break;
      }
      if (grew) {
        idleBatches = 0;
        continue;
      }
      if (!listing.hasMore && listing.scrollTop + listing.clientHeight >= listing.scrollHeight - 12) {
        queryStopReason = 'all_results_loaded';
        break;
      }
      idleBatches += 1;
      if (idleBatches >= 2) {
        queryStopReason = 'no_new_results';
        break;
      }
    }

    if (!queryStopReason) queryStopReason = 'tile_batch_cap';
    if (queryStopReason === 'query_failed') {
      tileFailureCount += 1;
      consecutiveTileFailures += 1;
    } else {
      consecutiveTileFailures = 0;
    }
    searches.push({
      pass: 1,
      search_zoom: COVERAGE_ZOOM,
      search_url: searchUrl,
      search_center: tile.center,
      search_radius_stage_km: stageRadiusKm,
      tile_index: tileIndex,
      tile_distance_km: tile.distance_km,
      status: queryStopReason === 'all_results_loaded' ? 'complete'
        : queryStopReason === 'limit_reached' ? 'target_met' : 'partial',
      stop_reason: queryStopReason,
      unique_candidates_seen: seenPlaceIds.size - candidatesBeforeSearch,
      records_added: recordsById.size - recordsBeforeSearch,
      batches_loaded: queryBatchesLoaded,
      has_more_results: Boolean(listing?.hasMore)
        || ['tile_batch_cap', 'no_new_results', 'query_failed'].includes(queryStopReason),
      error: loadError,
    });
    if (browserUnavailable || (queryStopReason === 'query_failed' && consecutiveTileFailures >= 2)) {
      stopReason = 'query_failed';
      break coverageSweep;
    }
    if (queryStopReason === 'tile_batch_cap') {
      // The batch cap applies to this tile only. Continue to neighboring tiles so
      // the collector can still meet the requested count within its bounded grid.
      tileCapReached = true;
      stopReason = 'tile_cap';
    }
    if (queryStopReason === 'limit_reached' || queryStopReason === 'safety_cap') {
      stopReason = queryStopReason;
      break coverageSweep;
    }
  }
}

if (recordsById.size >= effectiveLimit) stopReason = requestedLimit ? 'limit_reached' : 'safety_cap';
else if (!requestedLimit && !tileCapReached && tileFailureCount === 0) stopReason = 'max_radius_reached';
else if (requestedLimit && recordsById.size >= requestedLimit) stopReason = 'limit_reached';
else if (tileCapReached) stopReason = 'tile_cap';
else if (tileFailureCount && recordsById.size < effectiveLimit) stopReason = 'query_failed';
else if (recordsById.size < effectiveLimit) stopReason = 'max_radius_reached';

const records = Array.from(recordsById.values()).slice(0, effectiveLimit);
const requestedCountMet = requestedLimit === 0 ? null : records.length >= requestedLimit;
const finalSearches = SEARCH_ZOOMS.map((zoom) =>
  searches.slice().reverse().find((search) => !search.tile_index && search.search_zoom === zoom)
).filter(Boolean);
const hasMoreResults = searches.some((search) => search.has_more_results);
const centerZoomsExhausted = SEARCH_ZOOMS.every((zoom) =>
  searches.some((search) => !search.tile_index && search.search_zoom === zoom
    && ['all_results_loaded', 'limit_reached'].includes(search.stop_reason))
);
const allCoverageTilesExhausted = !tileCapReached && tileFailureCount === 0
  && searches.filter((search) => search.tile_index).every((search) => search.stop_reason === 'all_results_loaded')
  && tileSearchCount === coverageTiles.length;
const allZoomsExhausted = centerZoomsExhausted && allCoverageTilesExhausted;
if (!stopReason) {
  if (requestedCountMet) stopReason = 'limit_reached';
  else if (records.length >= SAFETY_MAX_RESULTS) stopReason = 'safety_cap';
  else if (searches.some((search) => search.stop_reason === 'query_failed')) stopReason = 'query_failed';
  else if (tileCapReached || searches.some((search) => search.stop_reason === 'tile_batch_cap')) stopReason = 'tile_cap';
  else if (searches.some((search) => search.stop_reason === 'batch_cap')) stopReason = 'batch_cap';
  else if (searches.some((search) => search.stop_reason === 'no_new_results')) stopReason = 'no_new_results';
  else stopReason = requestedLimit ? 'max_radius_reached' : 'max_radius_reached';
}

// Phase 5: persist records and report collection completeness separately.
let collection = null;
let collectionSaveError = null;
if (records.length) {
  try {
    collection = await tobub.data.save(records.map((record) => ({
      type: 'google-maps-business',
      id: record.id,
      payload: record,
      meta: {
        location_input: locationInput,
        resolved_coordinates: center,
        search_urls: [...new Set(searches.map((search) => search.search_url))],
        search_zooms: [...new Set(searches.map((search) => search.search_zoom))],
        search_radius_km: MAX_SEARCH_RADIUS_KM,
        coverage_tile_count: tileSearchCount,
        coverage_tile_step_km: coverageTileStepKm,
      },
    })), {
      name: 'google-maps-nearby-stores',
      mode: 'event',
      outputs: [{ type: 'file', format: 'jsonl' }],
      policy: { maxRecords: effectiveLimit, maxBytes: 10485760 },
    });
  } catch (error) {
    collectionSaveError = String(error?.message || error || 'Collection persistence failed.');
  }
}

let databaseSaved = 0;
let databaseSaveFailures = 0;
for (const record of records) {
  try {
    await tobub.db.saveContent({
      platform: 'google_maps',
      contentType: 'business',
      externalId: record.id,
      title: record.name || 'Google Maps business',
      summary: record.address || record.category || '',
      url: record.url,
      metadata: {
        category: record.category,
        rating: record.rating,
        reviews_count: record.reviews_count,
        phone: record.phone,
        website: record.website,
        hours: record.hours,
        latitude: record.latitude,
        longitude: record.longitude,
        found_at_zooms: record.found_at_zooms,
      },
      rawData: record,
    });
    databaseSaved += 1;
  } catch {
    databaseSaveFailures += 1;
  }
}

const collectionPersisted = records.length === 0
  || (!collectionSaveError && collection?.status === 'completed'
    && collection?.recordCount === records.length && collection?.droppedCount === 0);
const targetSatisfied = requestedLimit > 0 && requestedCountMet === true;
const allResultFeedsExhausted = requestedLimit === 0 && allZoomsExhausted;
const queryFailures = searches.filter((search) => search.stop_reason === 'query_failed').length;
const persistenceComplete = databaseSaveFailures === 0 && collectionPersisted;
const status = persistenceComplete && queryFailures === 0
  && (targetSatisfied || allResultFeedsExhausted)
  ? (records.length ? 'ok' : 'empty')
  : 'partial';
const searchUrl = searches[0]?.search_url || searchUrls[0];

return {
  status,
  location_input: locationInput,
  resolved_coordinates: center,
  search_radius_km: MAX_SEARCH_RADIUS_KM,
  initial_search_radius_km: INITIAL_RADIUS_KM,
  max_search_radius_km: MAX_SEARCH_RADIUS_KM,
  coverage_tile_step_km: Number(coverageTileStepKm.toFixed(3)),
  coverage_tile_count: tileSearchCount,
  coverage_tile_limit: MAX_COVERAGE_TILES,
  coverage_tile_failures: tileFailureCount,
  search_zoom: SEARCH_ZOOM,
  search_zooms: [...new Set(searches.map((search) => search.search_zoom))],
  coverage_mode: 'multi_zoom_overlapping_map_tiles',
  coverage_note: 'Searches start at the coordinate center, then move through overlapping map-sized coordinate tiles from nearest to farthest, expanding the accepted radius in 1 km stages up to max_search_radius_km. Place IDs are deduplicated and results are distance-sorted from the original center. The tile grid is bounded; Google Maps ranked feeds do not guarantee every business in the area is indexed or returned.',
  search_url: searchUrl,
  search_urls: [...new Set(searches.map((search) => search.search_url))],
  searches,
  coverage_tile_centers: searches.filter((search) => search.tile_index).map((search) => ({
    tile_index: search.tile_index,
    center: search.search_center,
    distance_from_center_km: search.tile_distance_km,
    radius_stage_km: search.search_radius_stage_km,
    stop_reason: search.stop_reason,
  })),
  query_failures: queryFailures,
  requested_limit: requestedLimit,
  requested_count_met: requestedCountMet,
  collected: records.length,
  candidates_seen: seenPlaceIds.size,
  excluded_out_of_radius: outOfRadiusCount,
  excluded_missing_coordinates: missingCoordinatesCount,
  excluded_accommodation: excludedAccommodationCount,
  batches_loaded: batchesLoaded,
  stop_reason: stopReason,
  has_more_results: hasMoreResults,
  database_saved: databaseSaved,
  database_save_failures: databaseSaveFailures,
  collection_persisted: collectionPersisted,
  collection_save_error: collectionSaveError,
  records,
  collection,
};
